create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,name text,email text,club text,role text default 'driver');
create table if not exists drivers(profile_id uuid primary key references profiles(id) on delete cascade,classes text[] default '{}',experience text,endurance_experience text,bio text);
create table if not exists rounds(id uuid primary key default gen_random_uuid(),name text not null,event_date date not null,venue text);
create table if not exists driver_availability(driver_id uuid references drivers(profile_id) on delete cascade,round_id uuid references rounds(id) on delete cascade,status text not null,primary key(driver_id,round_id));
create table if not exists teams(id uuid primary key default gen_random_uuid(),name text not null,manager_id uuid references profiles(id),club text);
create table if not exists team_drivers(team_id uuid references teams(id) on delete cascade,driver_id uuid references drivers(profile_id) on delete cascade,round_id uuid references rounds(id) on delete cascade,primary key(team_id,driver_id,round_id));
create table if not exists team_shortlist(manager_id uuid references profiles(id) on delete cascade,driver_id uuid references drivers(profile_id) on delete cascade,created_at timestamptz default now(),primary key(manager_id,driver_id));create table if not exists conversations(id uuid primary key default gen_random_uuid(),team_id uuid not null references teams(id) on delete cascade,driver_id uuid not null references drivers(profile_id) on delete cascade,round_id uuid not null references rounds(id) on delete cascade,created_at timestamptz default now(),unique(team_id,driver_id,round_id));
create table if not exists messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations(id) on delete cascade,sender_id uuid not null references profiles(id),body text not null,created_at timestamptz default now(),read_at timestamptz);
alter table profiles enable row level security;alter table drivers enable row level security;alter table rounds enable row level security;alter table driver_availability enable row level security;alter table teams enable row level security;alter table team_drivers enable row level security;alter table conversations enable row level security;alter table messages enable row level security;alter table team_shortlist enable row level security;
create policy "p1" on profiles for all to authenticated using(true) with check(true);create policy "p2" on drivers for all to authenticated using(true) with check(true);create policy "p3" on rounds for all to authenticated using(true) with check(true);create policy "p4" on driver_availability for all to authenticated using(true) with check(true);create policy "p5" on teams for all to authenticated using(true) with check(true);create policy "p6" on team_drivers for all to authenticated using(true) with check(true);create policy "p7" on conversations for all to authenticated using(true) with check(true);create policy "p8" on messages for all to authenticated using(true) with check(true);create policy "p9" on team_shortlist for all to authenticated using(true) with check(true);
insert into rounds(name,event_date,venue) select * from(values('Round 1 – Winter Enduro','2026-11-15'::date,'Example RC Club'),('Round 2 – Spring 6 Hour','2027-02-14'::date,'Example RC Club'),('Round 3 – Summer Endurance','2027-05-16'::date,'Example RC Club'))v(name,event_date,venue) where not exists(select 1 from rounds);